GRANT USAGE ON SCHEMA pgboss TO causedeck_clerk;--> statement-breakpoint
DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT c.oid::regclass AS rel, c.relkind, string_agg(DISTINCT acl.privilege_type, ', ') AS privs
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      CROSS JOIN LATERAL aclexplode(c.relacl) acl
     WHERE n.nspname IN ('public', 'pgboss')
       AND c.relowner = current_user::regrole
       AND c.relkind IN ('r', 'p', 'v', 'm', 'S')
       AND acl.grantee = 'causedeck_app'::regrole
     GROUP BY c.oid, c.relkind
  LOOP
    EXECUTE format('GRANT %s ON %s %s TO causedeck_clerk', r.privs,
      CASE WHEN r.relkind = 'S' THEN 'SEQUENCE' ELSE 'TABLE' END, r.rel);
  END LOOP;
  FOR r IN
    SELECT DISTINCT p.oid::regprocedure AS fn
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      CROSS JOIN LATERAL aclexplode(p.proacl) acl
     WHERE n.nspname IN ('public', 'pgboss')
       AND p.proowner = current_user::regrole
       AND acl.grantee = 'causedeck_app'::regrole
       AND acl.privilege_type = 'EXECUTE'
  LOOP
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO causedeck_clerk', r.fn);
  END LOOP;
END
$$;--> statement-breakpoint
