CREATE FUNCTION app_clerk_view(base regclass, view_name text, excluded_columns text[]) RETURNS void
  LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp
  AS $$
  DECLARE
    missing text[];
    cols text;
  BEGIN
    IF coalesce(cardinality(excluded_columns), 0) = 0 THEN
      RAISE EXCEPTION 'app_clerk_view: no columns to exclude from %', base;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.oid = base AND c.relforcerowsecurity) THEN
      RAISE EXCEPTION 'app_clerk_view: % is not under FORCE ROW LEVEL SECURITY', base;
    END IF;
    IF EXISTS (
      SELECT 1 FROM pg_policy p
       WHERE p.polrelid = base AND (SELECT oid FROM pg_roles WHERE rolname = 'causedeck_owner') = ANY (p.polroles)
    ) THEN
      RAISE EXCEPTION 'app_clerk_view: % has a policy for causedeck_owner, which the view would run as', base;
    END IF;
    SELECT array_agg(x) INTO missing
      FROM unnest(excluded_columns) AS x
     WHERE NOT EXISTS (
       SELECT 1 FROM pg_attribute a
        WHERE a.attrelid = base AND a.attname = x AND a.attnum > 0 AND NOT a.attisdropped
     );
    IF missing IS NOT NULL THEN
      RAISE EXCEPTION 'app_clerk_view: % has no column(s) %', base, missing;
    END IF;
    SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY a.attnum) INTO cols
      FROM pg_attribute a
     WHERE a.attrelid = base AND a.attnum > 0 AND NOT a.attisdropped
       AND NOT (a.attname = ANY (excluded_columns));
    IF cols IS NULL THEN
      RAISE EXCEPTION 'app_clerk_view: excluding % leaves no columns of %', excluded_columns, base;
    END IF;
    EXECUTE format('CREATE VIEW %I WITH (security_barrier = true) AS SELECT %s FROM %s', view_name, cols, base);
    EXECUTE format('REVOKE ALL ON %s FROM causedeck_clerk', base);
    EXECUTE format('REVOKE ALL ON %I FROM PUBLIC, causedeck_app, causedeck_clerk', view_name);
    EXECUTE format('GRANT SELECT ON %I TO causedeck_app, causedeck_clerk', view_name);
  END
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_clerk_view(regclass, text, text[]) FROM PUBLIC;
